qjet=[one]+[zero]*N
for rj in rootjets:
 fac=[S.Poly(x-rj[0],x,domain=dom)]+[S.Poly(-rj[j],x,domain=dom) for j in range(1,N+1)];qjet=[sum((qjet[k]*fac[j-k] for k in range(j+1)),zero) for j in range(N+1)]
