 C=64-delta*delta;nu=np.sqrt(max(0,2*delta*delta-64));rp=np.sqrt(5+np.array([-1,1])*np.sqrt(8+nu));rm=np.sqrt(5+np.array([-1,1])*np.sqrt(8-nu));mus=np.unique(np.round(np.sort(np.r_[rp,-rp,rm,-rm]),13))
